insert into public.theories (id, question_id, legacy_author_key, identity_mode, thesis, paragraphs, change_mind, status, dmz_pick, starter, needs_review, legacy_url, created_at, published_at) values
  ('l3893', 'what-happens-when-we-die', 'delerium', 'name', null, array['Life is dream-like to say the least. Most of us have no recollection of what happened before we were born. Looking back at one’s past, even the present, seems as hazy and obscure as a dream does. It is common knowledge that it is impossible to die in a dream – that doing so will jolt you awake. Why would this dream-like experience of life be any different? To die in this dream is to be born into another.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/sapiens-3-5-3/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4089', 'what-happens-when-we-die', 'chiron', 'name', null, array['It depends how you define what death is. It also depends who you define as you. Death of body is recycled into the Earth to become new resources for new Life to emerge. Death of the mind is the death of one’s identity and ideas – this can happen before the death of the body or at the same time. Accumulation of mind will be passed on through one’s consciousness – just like saved data stored in an iCloud rather than a hard drive only to be transferred back to the hard drive during reincarnation.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/sapiens-3-5-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l5583', 'what-happens-when-we-die', 'miranda-d', 'name', null, array['ABSOLUTELY FUCK ALL! We die. End of story. Our bodies decompose (unless we put them into a treated box, smh), and our energy is restored into the biosphere to make room for new life. To make things a little more romantic, I like to think that we are all just a transfer of energy, stored in bodies that can do miraculous things for the duration of our lives, and when we die we return to source, that dying is just returning.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/what-happens-when-we-die/', '2020-05-24T12:00:00Z', '2020-05-24T12:00:00Z'),
  ('l5616', 'what-happens-when-we-die', 'bekk-w', 'name', null, array['I’m open to everything, closed to nothing. Maybe we create our own afterlife, and whatever you believe to be the destiny of your consciousness, you manifest yourself. Maybe it’s reincarnation. Either way I believe it’s ashes to ashes and dust to dust- mother earth will repurpose your physical body no matter what. But that was never the question. We know what happens to our bodies when we die. It’s the idea of a “soul” that’s troubling. Does our soul continue on? It feels right to me that we are all a part of one consciousness on the pursuit of experiencing ourselves and becoming “God” over years and years of reincarnation, and maybe not even in a linear way.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/what-happens-when-we-die-2/', '2020-05-26T12:00:00Z', '2020-05-26T12:00:00Z'),
  ('l5709', 'what-happens-when-we-die', 'j-ban', 'name', null, array['A friend who has worked in hospice care once told me that people either die saying, ‘Oh God’ or, ‘Oh shit.’ I had witnessed two deaths by the time she told me that, my step-mother’s and my grandmother’s. Both ‘Oh shit’s’. My grandmother’s final words from her deathbed were, ‘That’s all?’ I don’t know who she was talking to, whether it was us or her God. It might have been that she was responding to someone or something that had, in the final breath of her life, finally revealed to her the purpose of life. And she was like, ‘That’s it?! Just that?’ The way it felt, knowing her choices from a young age had been dictated by historical fate and circumstance, was that she was saying, ‘I’m out of time already? That’s it, game over?’', 'That same hospice friend also said that the last sense to go was the sense of sound. That for a few minutes after clinical death, the deceased may still be listening. Moments after my grandmother passed, as my Orthodox Jewish aunt quickly covered her up with a white sheet, my mom pulled it down again brusquely, saying she wanted to look at her mother and say a few things to her. The two had a little fight right then and there. After a long life on the planet, the last thing Elfi would’ve heard was the adult version of what she witnessed countless times as the mother of these two: my strong-willed mother, the elder of her four brothers and sisters, and the next-oldest sibling, Judy, fighting over her dead body. Sheet up. Sheet down. Sheet up. Sheet down. My grandmother’s face skin jiggling stoicly as if she was feigning sleep.', 'But it didn’t matter. Elfi was now hovering on the other side of the room, looking out the window, a 20-year-old version freshly released from an 80-something year-old body 60 years too late. The voices of my mom and Judy faded into the background as she surveyed the world ; as if she’d realized, just after death, that she had needlessly sacrificed all of her own wants and needs for those of her husband, her kids, and later for her “shoulds.” She had “should” all over herself from the moment she had accidentally become a mother through her first sexual experience. The Elfi hovering near the window was the last iteration of my grandmother as her own person, the last time she felt more excited about what was ahead of her than what was behind.', 'Though all of us age, not all of us get older. Getting to know people, you can sometimes find that they stopped at a certain time, their spirit stuck in one spot while their body keeps moving like a Swiss train, staying on schedule with its fate and eventual terminus. Therapists see this all the time, and it could be said that their job is to dislodge the stuck spirit like guiding a fish around a dam, allowing it to rejoin the flow of life that has been rushing by.', 'I’ve seen it repeatedly in people who have been abused as kids or sexually assaulted. Maybe the offense happened repeatedly between the ages of 8 and 12, and though the person has since gone on to have kids and even grandkids of their own, to have what appears to be a mature adult life from the outside, their sentiments, their preferences, their way of being in the world is stuck swirling in an eddy at 12. Events happen to them rather than with or near them. They are victims of the world rather than active participants and co-creators.', 'No amount of trying to help someone stuck in victimhood will work because, if things improve, it will challenge their identity, the way they see the world. And if that happens, they won’t know who they are anymore. Terrifying. So best to keep complaining about that shitty neighbor or husband or friend, or to keep that shed as it is, full of stuff that needs to be moved, sold, or thrown away. To have something to be a victim of. Something to bump up against to prove you exist.', 'And it’s not just trauma that can trap a spirit safely near familiar shores. It may also be that someone has identified with a certain epoch as the highlight of their life and they’ve never left that time, they’re still there. When they were the big man or woman on campus, the head cheerleader, the captain of the football team; the person other people looked up to or wanted to be for a fleeting moment. The last time they remember being happy, being fully in the moment—which may have been the last time they didn’t remember anything at all. That fleeting moment, whether it be an experience of greatness, scoring the winning touchdown or successfully selling a business or a having hit song, becomes stamped on their soul, like a brand on livestock. It owns them, determines how they see themselves, who they belong to. The spirit of adventure, of curiosity about the world, diminishes as time and experience moves on and they are stuck, tethered like a dog to a pole outside a market, waiting for their moment to be reanimated. What we don’t realize is that the leash holding our wild, curious, resilient self in place is, in reality, just a thin tendril of frayed string.', 'A wild male African elephant can be over 20 feet long, 10 feet tall, and weigh 6 tons or more. And yet an elephant handler can lead it around with a small rope tied to one of its powerful legs, a leg bigger and thicker than the man himself. In training the elephants to become docile and easily controlled, the trainer starts them off when they are young and small and still easy to control, tying them with a thick chain they cannot break. As they get older and stronger and realize it’s no use to struggle, the mahout trades the chain in for a rope, and by the time the elephant is a large adult, can tie it with a strong string, knowing full well that the animal will not struggle against it, in spite of the fact that a series of hard tugs could easily set it free.', 'My friend Tim travelled extensively in India. He once told me the story of a fire that broke out in a small compound housing several trained elephants. It was night, and no one was around when it started. As it quickly spread through the straw on the ground and into the weak wooden walls and ceilings, the high-pitched trumpets and screams of the animals inside quickly became a chorus, a cacophony of fear. As bystanders gathered and stood at a safe distance, a local homeless girl 7 years of age ran in amidst the panicked pachyderms and easily freed all but one of them. It was easy, because they were each tied by a tiny rope attached to a leg. The learned helpless of the adult elephants nearly killed them.', 'The body doesn’t speak English. It speaks in symptoms, each symptom a sign of needed action. Looking into someone’s eyes, you can see the state of the world under their skin. When the whites of the eyes become yellowed, that’s the closed captioning of the liver saying, ‘Help! I’m overwhelmed. I’ve had all I can take and I’m going to throw all of my furniture into the street!’ In many pre-modern medical traditions, it’s not just outside substances that can harm the liver or any other organ. Emotions can as well. Excessive anger, repressed rage, can affect the liver, spiking blood pressure, causing all manner of harm. The Kidneys are affected by fear (even making some people pee). The Lungs, repressed grief. And so on.', 'And it’s not just “negative” emotions that can harm us.', 'An excess of ‘joy’ harms the heart. (The word for the state of someone’s heart, ‘xin,’ may also be translated as the word for ‘mind.’) We’ve all known people who seem so happy that they cannot stop talking excitedly, unable to “contain” themselves. Some part of us knows that this ‘happiness’ is pathology, perhaps even diagnosable as manic. No one can handle being around such a person for long. That’s an issue of the heart in relation to the pericardium. In modern medicine, the heart is protected by a sac that contains it. In traditional Chinese medicine, it’s the wall that protects and holds it. The pericardium is failing to contain the heart.', 'The whole concept of each system in traditional Chinese philosophy isn’t just about its function; it has a symbolic, energetic dimension as well. The pre-Communist Chinese modeled everything after their politics. The north star was the Emperor, never moving, ruling the heavens as they moved and circled and spun around it. The heart is the emperor of the body. The Liver is the general in charge of the army (the blood). The spleen/stomach the head of agriculture, the granary official, and so on. The universe and their kingdom were mirrors of one another, as was every aspect of life on earth. Hence the emperor being associated with heaven, and vice-versa.', 'Oh, I could go on and on about the symbology and story lines connecting traditional medicine to what we see in the world, but all of this here, now, is to say that the extremes of our remembered experiences can get us stuck like a record repeating itself, caught in the same groove as the turntable keeps moving around and through us.', 'The limitations we face are almost entirely of our own creation, and all it takes is a few sharp tugs to break the string that we perceive as a chain.', 'Don’t believe me? Ask someone on their deathbed.', 'Bronnie Ware is an Australian nurse who worked in palliative care for many years with people in the final light of the sunset of their lives. Over time she saw many patterns, recording them in a now-famous blog post about the regrets of the dying. (https://bronnieware.com/blog/regrets-of-the-dying/). The top five:', 'I wish I’d had the courage to live a life true to myself, not the life others expected of me.
I wish I hadn’t worked so hard.
I wish I’d had the courage to express my feelings.
I wish I had stayed in touch with my friends.
I wish I had let myself be happier.', 'I’ve read through this and many other articles and books about the purpose of life, what it means to live a life worth living, and I have yet to find anything that said, ‘I wish I worked more,’ ‘I wish I’d taken less time for myself,’ or ‘I wish I’d taken fewer risks.’', 'There’s no better way to be fully present than to put yourself in harm’s way. Releasing yourself back into the wild, the qualities that will help you to survive and thrive may not be the same as those that got you to succeed before. Where before we got food pellets for conforming and going along with the system, hunting down your own game requires curiosity, innovation, and resilience. It can be approached with fear, or the excitement that comes with opportunity. Or both.', 'Being fully educated and acculturated, it can be difficult to remember that you are bigger and more capable than what you’ve been taught to believe and go along with. Your education and upbringing are held within you, but they are not you. They are simply tools. When you fully realize this fact, you also suddenly see that the keys to your cage have been in your pocket, and that the door has in fact been unlocked all along.', 'A Taoist quote says, ‘A man is born gentle and weak; at his death he is hard and stiff. All things, including the grass and trees, are soft and pliable in life; dry and brittle in death. Stiffness is thus a companion of death; flexibility a companion of life. An army that cannot yield will be defeated. A tree that cannot bend will crack in the wind. The hard and stiff will be broken; the soft and supple will prevail.’', 'You are as lithe, flexible, and malleable as you allow yourself to be. The qualities needed to risk into the life ahead of you are not the qualities that got you good grades or saw you climb the corporate ladder. Rather, curiosity, flexibility and grit are what will see you through. And while the prospect of risking into the new world when you’re already mindlessly acclimatized to your reality may not sound all that palatable, the intangible rewards of the experiences you’ll have will see you die with many fewer regrets.', 'This is what my grandmother’s spirit was saying as it stared out the window just moments after her death, saying ‘Oh God’ just moments after saying, ‘Oh shit.’ My grandma waited until she was out of her body to learn it. You still have time.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/sapiens/sapiens-3-5-8/', '2020-05-28T12:00:00Z', '2020-05-28T12:00:00Z'),
  ('l5869', 'what-happens-when-we-die', 'vesela-m', 'name', null, array['The process of dying has been explained in detail by many indigenous tribes and ancient sciences. I have chosen to read and study Tibetan Buddhism, Vedic Teachings, and Tantric Practices. This is an attempt to present, in short, my understanding of the process of dying and rebirth according to the teachings I mentioned above. If you want to read more, I highly recommend the Tibetan book of living and dying by Sogyal Rinpoche. The human organism is sustained by 5 elements-earth, water, fire, air and space. Once we die, the elements dissolve into the macro universe. Together, with the elements, in specific order the ego, intellect, conceptual mind disintegrate as well-stripping everything away from us-senses, emotions, feelings, rational thinking until nothing else remains but our true nature/consciousness/soul/ higher-self/spirit-whatever you need to call it.', 'This is where the practice of meditation can help one remain connected to the source and not get lost in the many layers of illusion that the dying mind will create. Without the familiar physicality, the mind is very powerful. As each thought can easily become reality, every irritation or bad habit, or fear can send the dying person into a helpless and scary spiral of load sounds, colors and hallucinations. If you lose connection with your true essence and give in to the projections of the mind you will be reborn back to the cycle of samsara. You will have many many opportunities presented during the process of dying to escape the cycle of life and death. That’s why the moment of death is considered to be extremely important. We can even, suggest that we live to prepare to die.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/sapiens-3-5-9/', '2020-05-31T12:00:00Z', '2020-05-31T12:00:00Z'),
  ('l6110', 'what-happens-when-we-die', 'tyler-k', 'name', null, array['There is no heaven or hell, or spiritual plane, or even eternal void you go to when you die. Just an infinitude of an inevitable conscious experience of self-worlds. Eternal hell could never exist, nor eternal heaven. Nothing ever remains in the same place forever. The experiencing world NEEDS contrast. If the up line means you’re happy and the down line means you’re sad then If you were always going up you wouldn’t have anything to relate to happiness to give it its meaning of happiness. No down line to know what up is or what it means at all, it wouldn’t be happiness anymore. You only know you’re happy because you’ve been sad. Everything is bound to change and it would need to be naturally.', 'This is the part we often refuse to accept in my opinion. We want imperturbable happiness and can’t get it and wonder why. You can’t stare at just one color and see difference, you need the contrast of other colors. So how could these spirits just self experience in one place (heaven or hell) never moving from that place/ state with no contrast for eternity? Seeing only one color is equal to experiencing void. If you only saw all white (heaven (eternal bliss)) or all black (hell (eternal suffering)) there would be absolutely nothing to see. We lose touch with what it means to be happy because sadness gives happiness its meaning and purpose. Without sadness how could we know the value of happiness? And vice versa. We are truly only able to see and feel by contrast and change.', 'This belief of heaven and hell is founded on the idea that God created these beings under these circumstances (as if God had no influence or connection to the situation at all… yet he/shes god theirself) and made it up to god’s subjects to decide, putting the decision on Gods subjects, fully knowing of their sinful nature as he created them that way and if they failed which is likely since god made them sinful, they deserve to suffer eternally in hell? What kind of God would we be worshipping then? God would be too intelligent to create sinful beings just to command them to worship and be like his ONLY unattainably divinely perfect son god has EVER had (disowning the rest of existence as gods children) and condemning the beings God made in sinful nature for not acting in divine ways like his son when god theirself created them in that way. That makes absolutely no sense if god is supposed to be all knowing and of the highest intelligence?', 'I don’t see God as watching from the sidelines in the void saying to itself “ooo lets see what that guy’ll do” at the ready to deliver divine justice. Hah no. I see God tilling the fields personally. I see god blowing the breeze. I see god on the frontlines AS nature. That is why I do not believe in a heaven and hell beyond your present state of experience. So I really can’t get with this idea. Because I’ve felt so much from personal experience that contrasts christianities primal belief that God is seperate from you. God would never create a situation where there is eternal suffering, because God/Nature is the one experiencing it. Who else other than god/nature could actually experience it? There’s noone-nothing else here? So what you truly are is the primordial source of any arisal. The inextinguishable. I believe our experience may blend into the next, moving on from one painting to the next. Not that your experience is now lost in void. There is nothing to be experienced in the void. It’s impossible to not experience anything, even if you’re not conscious of yourself as yourself. But since there are countless self experiencers being born into the world in every moment, it’s unnecessary to worry about losing self experience to the void, for you are self experiencing now aren’t you? And the same self that sits in you sits in all self experiencers.', 'Self /god/nature is at the center of everything. So when you die I feel the individual you simply dies, or fades from experience. Though you can’t experience void of experience. So inevitably there is evercoming self experience. However it happens though I am not sure. Too many unclear variables from my limited relative perspective. On the premise that happening-consciousness are universal constants,,I feel it’s more like this: Red has its place as a color in the spectrum of colors. Although it shows its unique characteristics to the world it still blends back into the spectrum of everything from before its birth and after its end. Yet between its beginning and end, it colors and lights the world with its particular brush stroke, (your conscious experience-expression). Just because there isn’t red in a painting, doesn’t mean red is dead. It’s just not being experienced right now, but this blue painting is! My main point is you can’t experience non-void, and you can’t experience the same feeling/experience (heaven or hell) forever. The only thing that’s left standing is an inevitability of experience.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/what-happens-when-we-die/sapiens-3-5-10/', '2020-06-20T12:00:00Z', '2020-06-20T12:00:00Z'),
  ('l3891', 'what-separates-humans-from-other-life-forms', 'starseed', 'name', null, array['Humans are the most conceited species to have ever existed. We have long promoted the myth that we are ‘special’, yet there is little evidence to support the claim. Perhaps our species is unique, just as a tick or a bear is unique, but are we anything special? We are a rather young species – only 200,000 years old – perhaps we would be well served by learning from the species that have been around for longer than we. But instead, we rape and pillage, diminish ecosystems, and thrust the Earth out of balance.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/sapiens-3-3-2/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l3889', 'what-separates-humans-from-other-life-forms', 'joleen-s', 'name', null, array['Humans are unique in a number of ways – from wearing clothes to using fire to having traits like memory, empathy and language (to name a few). However, more than anything, our uniqueness lies in the psychological characteristic called Ego. We are the only creature on earth to consciously construct a ‘self’ that is separate from the rest of nature. This characteristic is fundamental in our evolution, whether we like it or not, and is the path for the evolution of consciousness – human and planetary.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/sapiens-3-3-3/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l3886', 'what-separates-humans-from-other-life-forms', 'the-kid', 'name', null, array['Humans are the most paradoxical species on the planet. While other species can act and feel, none can do so to the extent that we can. We have the capacity to experience the heights of heaven – love, beauty, joy – and also the depths of hell – hate, anger, jealousy, and in doing so, effect countless beings. We are grounded on Earth and yet dancing among the cosmos. We are each a blank slate to be shaped uniquely by our conditioning and state of mind. We are animal and god in one.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/sapiens-3-3-4/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4087', 'what-separates-humans-from-other-life-forms', 'chiron', 'name', null, array['The ability to respond to Life consciously and co-create intelligently with the cosmos through one’s own will. No being on Earth gets to make conscious choice. This is a curse and a blessing of being human. Misaligned choices bring calamity and aligned choices brings prosperity. We are made to co-create with the intelligence of the universe or what we call God. Human had been trying to figure this out all ages.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/sapiens-3-3-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l5581', 'what-separates-humans-from-other-life-forms', 'miranda-d', 'name', null, array['Humans have gone farther than other species’ in understanding and manipulating the world; matter, energy, the laws of physics, etc. While many other intelligent species have learned how to use tools and manipulate their environment to complete basic tasks such as feeding/surviving/mating, humans have learned to break matter down to its basic elements to create things not made from nature. Humans are also the only species that play God and use more resources than we need, as far as I’m aware. I think a lot of this speaks to our intelligence. If we’re simply defining intelligence as the capacity to learn, reason and solve problems, it’s clear that humans are the most intelligent species, which is why we’ve pretty much dominated the planet. Although, we have created as many problems as we’ve solved. But I think consciousness is a different story. I don’t think we know enough about consciousness to say that humans are the only conscious species. There’s the long withstanding argument that believing humans to be the only “conscious” species is egotistical. This gets into the whole “what is consciousness” debate, which is a different tangent, but the question of whether consciousness is what separates humans from other lifeforms can’t be answered until we understand more about it.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/what-separates-humans-from-other-life-forms/', '2020-05-24T12:00:00Z', '2020-05-24T12:00:00Z'),
  ('l5614', 'what-separates-humans-from-other-life-forms', 'bekk-w', 'name', null, array['A form of ‘consciousness’? But it’s hard to gauge because I’m using my limited human knowledge to measure another species. And the scale I’m using to make those measurements could be totally inept if there is knowledge I just don’t have to measure certain things. I don’t know if it’s fair to label beings more sentient than others, because, I don’t know what they know. It’s in the same vein as that Einstein quote- ‘If you judge a fish by its ability to climb a tree, it’ll live it’s whole life believing that it’s stupid.’ Maybe other creatures can’t write a dissertation, create artificial intelligence, or write a book of poems- but, maybe I don’t even know the kind of divine knowledge that is within them, and if I chalk it up to a hierarchal world, where us humans are at the top, and that’s that- I might rob myself of juicy discovery- Or the joy of wonder, at the very least.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/what-separates-humans-from-other-life-forms-2/', '2020-05-26T12:00:00Z', '2020-05-26T12:00:00Z'),
  ('l6108', 'what-separates-humans-from-other-life-forms', 'tyler-k', 'name', null, array['Other than naturally contrasting unique characteristics, any separating identifying belief. All organisms act out of their own need and have unique qualities and characteristics. Because we’re all different, that fact makes us the same. We are all equally alive in this world. You could say we are different because of our massive needs and desires vs other organisms who live simple unharmful lifestyles towards the environment. One unique characteristic i can name about humans vs others is no other organism has enslaved races or species of animals to work for them like we have. No other organism has made such a massive harmful impact on the ecosystem. But whos to say if kangaroos became the dominant species they would most likely do the same thing. Not realizing their affection until it starts causing bigger problems.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/what-separates-humans-from-other-life-forms/what-separates-humans-from-other-life-forms-3/', '2020-06-20T12:00:00Z', '2020-06-20T12:00:00Z'),
  ('l3884', 'who-and-or-what-are-we', 'starseed', 'name', null, array['We can’t possibly know who we are, just as the eyes can’t see the back of the head, how the nose can’t smell the stomach, how the ears don’t hear the brain, or how the hand can’t clap itself. Our organism is not designed to ‘know’ itself, but to dabble in delusion, to pursue in folly, to explore the hazy unknown. In just the same way, the human mind is designed to ask ‘why’, but not to receive’ the answer.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/sapiens-3-1-2/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l3882', 'who-and-or-what-are-we', 'delerium', 'name', null, array['We can’t know who we are unless we know who we are not. We have all been raised to believe in a false sense of self. All we can do is use the process of elimination – “I am not this. I am not that. I am not this body. I am not these thoughts. I am not this personality…” To be constantly remembering who we are NOT is to be chiseling away at our conditioning and excavating the jewel of who we truly ARE. That jewel can’t be described in words, thoughts, emotions, or anything else. It merely… is.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/sapiens-3-1-3/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l3880', 'who-and-or-what-are-we', 'chan-lee', 'name', null, array['We are a watercolor painting of the cosmos. Alone, we are each a brush stroke – some bright, some dark, each unique. As a whole, we are a masterpiece. Most of the strokes are dark, and most of us are still ignorant to our true nature. Once in a while, there is a bright star – a being who has awakened to the truth. Sometimes a cluster, or a galaxy – a community of beings who have begun to bring others towards the light. The dark and light need each other. Alas, a shooting star – and another!']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/sapiens-3-1-5/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l3878', 'who-and-or-what-are-we', 'the-kid', 'name', null, array['We are characters in a play – some of whom have played our parts so well that we have forgotten who we are off stage. We are also the audience, captivated by this incredible melodramatic comedy – many of whom have forgotten what is real. We are the camera crew, shining the spotlight on where the action is. We are also the director, who has curated the entire experience for everyone’s entertainment. We are all of these things.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/sapiens-3-1-4/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4085', 'who-and-or-what-are-we', 'chiron', 'name', null, array['We are human beings – beings with the ability to make conscious response. We are the Instrument of our solar system where our measurement of our bodies matches the sacred geometry of the universe through the phi ratio. We don’t exist by accident. The reason we have such consciousness and intelligence is because we are made with intent. Human history still remains in the dark and there are many yet to be discovered by science but is spoken through ancient myth of the many world traditions.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/sapiens-3-1-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l5612', 'who-and-or-what-are-we', 'bekk-w', 'name', null, array['I’ve reasoned that we’re meant to be stewards of the earth. We’ve been given a divine kind of consciousness that allows us to experience a sense of separation, duality- that is used to observe the world around us, our place in it, think of the past, and try to predict the future. I think we use this divinity rather selfishly (which lends to a lot of our psychological sickness, I think), where-as it could be best used to facilitate harmony. I think we all are different manifestations of the same energy source. To quote Deepak Chopra- “I am you, and you are me, only in disguise.” And to take the thought past only you, or me, and extend it to a flower, the mountain, a whale- brings me a lot of solace. There are times when I let my sense of duality fade, and I feel all mixed up with the world, and earth around me, and something about it feels so right- like home. But, I think it is with our sense of separation that responsibility steps in. We have a responsibility to heal and take care of the world around us.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/who-what-are-we/', '2020-05-26T12:00:00Z', '2020-05-26T12:00:00Z'),
  ('l5782', 'who-and-or-what-are-we', 'gissy-moon', 'name', null, array['We are children of God. We were created as a whole, complete soul. God created us to have the desire to incarnate on earth. With that spark of desire, as little souls we incarnated on earth. In that process, our soul splits into two halves. Each of those halves incarnates into a tiny fetus inside of our mothers. As soon as we incarnate, we now individually have two bodies attached to our soul. So we have our soul, our spirit body, and our physical body. All attached by a silver chord.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/who-what-are-we-2/', '2020-05-30T12:00:00Z', '2020-05-30T12:00:00Z'),
  ('l6103', 'who-and-or-what-are-we', 'tyler-k', 'name', null, array['We are the process of ever being nature. Some say we are just bodies seeing through nerve ends sent to be processed by the mind. Or others say we are just the eternal consciousness of self or maybe spirit. None of those are wrong, it’s just when you say it’s one way, you also say it’s not the other way. I feel Nature is a blend of all aspects in things, not one more needed but all integral parts for the fruition of existence. Being affects consciousness and vice versa. And the body is spirit, a part of the natural expression of the naturally occurring world. We think spirit is just in our chest or in or expressions or intentions, or in some spiritual plane beyond? It’s everywhere you look in my opinion. The natural world is the spiritual plane and you could say God or the Universal self is expressing itself with its spirit and we naturally are that and take part in that.', 'I say nature/natural because it doesn’t have any special associations with it and it is ‘what is’ in the natural world, unlike god, how it subconsciously infers some separate entity somewhere beyond pulling all the strings. Whatever is the true nature, left right up down, it is always itself and could never be disconnected with that selfness. For how could anything ever not be natural whether it is ourselves or god or anything. This world is functioning successfully without us trying to make it so. We just sort of inevitably find ourselves here, awake, and alive, but in this simple process the world is lit up by natural being. Because It is inevitable to experience in a universe with being-happening in it. The only other alternative is void, which is the void of experience itself which wouldn’t be an experience at all.', 'This question is one of the hardest questions to answer because I feel it is paradoxical, because it’s asking for a true description of who/what we are which is nature- everything by attempting to dissect nature into different parts when it’s not separate and we could never truly dissect it. We use it as tools for communicative purposes. To say it’s one way is to say it’s not the other way but nature is all possible ways in whatever way it does and could happen. And also I can’t tell you who or what I am unless there’s something different I can compare it to. Now if you’re asking my identity I can easily tell you that. Because those are our unique qualities. But the underlying essence of who we are is a constant in everything, so how can i begin to describe that? We are a combination of both of those things. Though still, there is nothing else to compare it to in order to serve you an edible dish of information. Because it is everything. The fundamental being that cannot be destroyed. If it were possible to extinguish the universe forever it would have already happened and we wouldn’t be here now.', 'If i were to simply answer i could answer it in 3 ways equally. I would answer, i am, because that answers the question not with words, but with natural unowned undefined, being as its own description. Isness, amness, thusness. I know its sort of a cliche answer but i feel it actually does a good job at pointing at the moon. It requires your genuine inquiry to find the answer in yourself. Or Source, the indestructible essence that underlies, sustains, and is everything. Lastly Nature, because it is the natural word, in natural processes that we find ourselves. Existence – non existence could never not be natural. No-thing could not be natural. Everything – nothing is inevitably natural. I am the natural world. Identity truly is not limited by boundaries of skin. Because all is inevitably self.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/sapiens/sapiens-3-1-9/', '2020-06-20T12:00:00Z', '2020-06-20T12:00:00Z'),
  ('l3876', 'how-did-the-universe-begin', 'eva-lenore', 'name', null, array['The Universe is made of explosions. Like an atomic bomb, these types of explosions are happening on both the micro and macro levels. From an atom, to our thoughts, to how plants and humans grow, there is a trend of emerging from a seed into an explosive creation. Our 14 billion year old Universe works the same way – birthed from a seed and will eventually burn out. It’s human nature to create beginnings and endings, but without us, this Universal explosion is among and within infinite explosions.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/universe/universe-3-6-2/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4081', 'how-did-the-universe-begin', 'chiron', 'name', null, array['The Universe has not begun and will not end. Principle of physics name that energy cannot be created and cannot be destroyed. Therefore, the Universe that is made up of energy cannot be created or be destroyed. What can happen is expansion and contraction of energy which brought forth existence and non-existence. Good luck finding the source of creation.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/universe/universe-3-6-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l5579', 'how-did-the-universe-begin', 'miranda-d', 'name', null, array['I don’t want to know. Is this not the mystery of life? Why are we here, where did we begin? The divine mystery of it all is what makes life so precious. What is existence without curiosity? I like to think that the universe never began, that there is no boundary to time and space, everything is just movement of energy. If the universe did begin somewhere, that would mean there is a starting point and eventually and ending point, and it also would point to the existence of some sort of higher power, because then everything isn’t just random: there was a single moment of change, of beginning, a conscious decision made.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/universe/how-did-the-universe-begin/how-did-the-universe-begin/', '2020-05-24T12:00:00Z', '2020-05-24T12:00:00Z'),
  ('l5622', 'how-did-the-universe-begin', 'matt-m', 'name', null, array['Its widely accepted that the Universe began with the discovery of the cosmic microwave background. This buzz of radiation expanding in every direction only makes sense if it developed from a much warmer early history of the universe. ‘Redshifts’ are the observed stretching of light from distant galaxies. The spectrum and distribution of the cosmic microwave background exactly matches expectations of the hot Big Bang. This is how the universe began. Just like how it started, life was able to form because of the process of entropy. The hot universe that was incompatible to life cooled enough to allow life to exist. With entropy, life was able to exist but it is also believed that entropy will lead to the end of the universe. However, NASA may have found evidence that there could be a universe parallel to ours where time moves backwards. As a result, the end in this universe could be the beginning in the next one.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/universe/how-did-the-universe-begin-and-or-how-will-it-end/', '2020-05-26T12:00:00Z', '2020-05-26T12:00:00Z'),
  ('l5604', 'how-did-the-universe-begin', 'bekk-w', 'name', null, array['I’m guessing with a bang, and probably another bang. What is an end though? An end to our species? An end to all life on earth? Our whole planet exploding violently into a million little pieces? I think life will always find a way. Our planet was born out of violence, and will probably be destroyed out of violence. But that is the circle of life. Life is full of beautiful and wondrous things, but the nature of the universe is volatile, but better yet, resilient.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/universe/how-did-the-universe-begin-and-how-will-it-end/', '2020-05-26T12:00:00Z', '2020-05-26T12:00:00Z'),
  ('l5778', 'how-did-the-universe-begin', 'gissy-moon', 'name', null, array['The universe began from Love, and it can end if humanity continues down a path of denying Gods love, denying our emotions, denying what we need to fix and heal. If humanity continues down a path of destruction, not just physically but emotionally, the laws of the universe will bring us consequences, to stop our unloving behavior.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/universe/how-did-the-universe-begin-2/', '2020-05-30T12:00:00Z', '2020-05-30T12:00:00Z'),
  ('l3874', 'what-is-time', 'starseed', 'name', null, array['Space-time is a plane of existence by which humans exist and abide. It appears to be an endless ocean of time and space, governed by gravity. Humans experience time in this linear way, confined by our limited intelligence and capacity. However, what if, like the Earth, the plane of space-time was actually round and cyclical? What if black holes were thus just vortexes which transcended traveling through space-time altogether, in essence allowing for time-travel? Cosmic Subways, if you will. Enter one and emerge from any others, anywhere in the Universe.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/universe/universe-3-5-2/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l3871', 'what-is-time', 'the-kid', 'name', null, array['Humans perceive time as something linear. For some, the future runs into the present, which runs into the past. For others, the opposite. For others, the present runs into both future and past. For others still, time does not exist at all. But we can’t deny that we are different than we were last year. Time, like walking towards the horizon, seems linear, but is actually cyclical. The past and future are not two ends of a spectrum but two directions on a circle.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/universe/universe-3-5-3/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l4079', 'what-is-time', 'chiron', 'name', null, array['Time is a creation of the mind and does not exists. Pasts are determined by memories and memories are not the past. Future are determined by concepts of the past about what is going to happen and through learned experiences of patterns. Time is a human construct made for referencing the universe that does not mean time exists in reality. What exists is the eternal moment of the present – everything and anything happens in this space of infinite possibilities.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/universe/universe-3-5-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l5573', 'what-is-time', 'miranda-d', 'name', null, array['Apparently, physicists have decided it’s impossible to travel back in time, only forward. Would anyone want to travel forward in time, not knowing what will await them and knowing they’d never be able to return? That’s quite a commitment.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/universe/what-is-time/', '2020-05-24T12:00:00Z', '2020-05-24T12:00:00Z'),
  ('l5606', 'what-is-time', 'bekk-w', 'name', null, array['Wear and tear. Death and rebirth.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/universe/what-is-time-2/', '2020-05-26T12:00:00Z', '2020-05-26T12:00:00Z'),
  ('l5705', 'what-is-time', 'drew-r', 'name', null, array['Time is a construct. I have often wondered if it is indeed necessary or not. I’m not going to get all ‘Hawking’, but rather keep this relatively simple. For the basis of this answer it is necessary to look at the two factors, which impact what we know as relative time as compared to absolute time. The two factors are the Rotation of the earth about its axis and the Revolution of the earth around the sun. The world as it now exists has the notable occurrence of the rise and fall of the sun, which occurs, in a regular pattern. This observed pattern gives us what we have named day and night. This pattern is due to the rotation of the earth about its own axis. Simultaneously, the earth is revolving around the sun. The revolution of the earth around the sun is responsible for the shift in seasons (anywhere from 2-4 seasons are experienced throughout the world). To quantify these changes time was constructed. Time as we know It uses 60 as its base. Sixty is a number with 12 factors. Now that the basics are laid out we can delve into the question of what is time?', 'Returning to my belief that time is a construct. Time as we know it is a mechanism to quantify regularly occurring effects of the rotation and revolution of the earth. However, why even quantify it? If we had no means of quantifying would the world be lost or dysfunctional? Probably not as the rotation and revolution of the earth would likely guide our actions. Or if we only had a running cumulative number would it really make any difference at all? Although the latter would be utilizing a form of time just with a structural change to how it looks.', 'Perhaps time is inescapable. The reason why it may be inescapable is that we observe the shifts in day / night and shifts in seasons or in other words we observe movement and change. These observations of movement and change, whether we care to quantify them or not, exist and will continue to exist. Time provides us with a reference to events that occurred (past), are occurring (present) and will occur (future).', 'As regular and inescapable as time may be, the experience of time does not remain regular or consistent, but rather is subjective. Think of yourself being lost in the moment of an enjoyable experience. Time as you know it can be perceived stopped or nonexistent for those moments. Now consider moments of pain. Time as you know it is not lost, but rather intensified. During those painful moments we may be acutely aware of each and every moment that passes. 
Regardless of our subjective experience, either moments of elation or pain, the earth’s position changes. Our subjective experience or perception, of the moments we experience, does not slow down or speed up the rate of change in the earth’s position. After each moment the earth is no longer at the same universal location it was at the moment before. In an effort to explain the changed location we have constructed a unit of measure we refer to as time.”', 'Links: 
Relative vs Absolute time:
https://www.calculator.net/time-calculator.html
Seasonal shifts:
https://www.abc.net.au/news/science/2017-09-01/seasons-and-their-changes-explained/8858776']::text[], null, 'live', true, false, true, 'https://quarxtheories.com/universe/universe-3-5-7/', '2020-05-28T12:00:00Z', '2020-05-28T12:00:00Z'),
  ('l6241', 'what-is-time', 'deanna-a', 'name', null, array['Time is an obsession of the modern man. But I believe it could once be simply described as ‘the changing of seasons’ or ‘when the berries come in.''']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/universe/universe-4-4/what-is-time-3/', '2020-07-05T12:00:00Z', '2020-07-05T12:00:00Z'),
  ('l3869', 'why-is-there-anything-at-all', 'j-dizzle', 'name', null, array['[et_pb_section fb_built=”1″ _builder_version=”4.4.7″ hover_enabled=”0″ da_disable_devices=”off|off|off” custom_padding=”0px|||||” background_color=”rgba(0,0,0,0)” da_is_popup=”off” da_exit_intent=”off” da_has_close=”on” da_alt_close=”off” da_dark_close=”off” da_not_modal=”on” da_is_singular=”off” da_with_loader=”off” da_has_shadow=”on”][et_pb_row _builder_version=”3.25″ background_size=”initial” background_position=”top_left” background_repeat=”repeat”][et_pb_column type=”4_4″ _builder_version=”3.25″ custom_padding=”|||” custom_padding__hover=”|||”][et_pb_text _builder_version=”4.4.4″ background_size=”initial” background_position=”top_left” background_repeat=”repeat”]', '“If time is circular then time itself never stops and space continually changes. Whether life in its basic form as micro-organisms can survive is determined by the environment space cultivates through time. If anything can be infinite such as time, then all things can be infinite. The mere existence of something being infinite implies that a circular system cultivating infinity can be applied to all things. What we experience on Earth is a snapshot understanding of how the universe is structured. We have layers of consciousness in how all species on Earth co-exist. We as humans think we are at the top of the food chain but if the concept of infinity can be applied to the layers of consciousness, why does it stop with us? Maybe some of us see God as a higher layer to us. Maybe some see natural disasters as higher layers to us. Basically, if something can kill us, we feel like we are below it. We cannot escape death and therefore it is a reality that cannot be changed. From the birth of consciousness to the infinite continuation of itself, there are structures in place so that consciousness can exist. If there is one singular energy/force/being that is trying to understand what it is, it must separate itself infinitely into every part of what it is. The reason why time is infinite is due to the fact that evolution is infinite as is consciousness. Essentially, consciousness will never fully realize itself or else it will realize it is completely alone and to be alone implies a lack of ‘other’ to respond to. To experience desire, we need something to desire. If there is only one, then there is no other to desire and therefore no reason for one. So consciousness continues experiencing itself through the responding to everything around which in turn is itself. With each new creation, fueled by fresh consciousness unable to go deep enough to fully realize what it is, life continues. Why does anything exist at all? The never-ending search by consciousness at trying to figure out what consciousness is through its own experience of itself and itself being an infinite evolving aspect of time and space. Combined with pure exhilarating, rich experience of emotion, sensation, meaning and non-meaning experiences while riding the wave of creation and destruction stemmed from any reason and no reason. The infinite layers of consciousness in material and non-material entities never stop. Just like we have dogs that we will never be able to explain why their lives are the way they are, the infinite layers of higher conscious beings/gods/aliens will never be able to explain to us why they do what they do. Ask yourself why you tease your dog sometimes? Maybe because you are bored and it gives you entertainment. If time and space never stops, all things can be enjoyed equally. But we are not a higher layer of consciousness to ourselves and so we seek meaning in our own realities. Layers below humans don’t ask why but how and so they accept what is. Layers above humans don’t ask why, they say why not?”', '[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section]']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/universe/universe-3-4-1/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l3867', 'why-is-there-anything-at-all', 'nick-s', 'name', null, array['It’s all for fun. It’s just a ride. A wave. A surfer rides the wave rather than opposing it. Everything in the Universe is riding the wave, following the path of least resistance. The stream is made of bliss – a bliss of pure awareness. Pure being, pure energy, pure celebration. For us, who have a complex form of consciousness, the bliss of existence can be disguised in our spectrum of emotions. For humans, love is the vessel into this space of pure bliss. That’s what it’s all about.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/universe/universe-3-4-2/', '2020-05-02T12:00:00Z', '2020-05-02T12:00:00Z'),
  ('l5263', 'why-is-there-anything-at-all', 'b-janszen', 'name', null, array['I hate to be the bearer of bad news, but what if I told you earth’s only purpose was created out of the shared galactic intention to bring peace into all realms. You’re probably wondering, okay why is that bad news to be the bringers of peace? And realms, what? It’s bad news because, let’s face it, as humans we are born alone and we die alone. We begin our existence from day uno with deep seeded trauma during birth. Some argue the soul enters the body after its born. For some beings this is true, but for others they have chosen to have the “premium” human experience option.', 'So let’s get to the juicy stuff now. Human consciousness is the product of needing balance. Each and every one of us has an energy signature, an ego, and an ability to experience through our senses or faculties. This is the biggest gift and the biggest curse. Our evolution was purposeful – to create a vessel which could support the mass amounts of information and experiences which define how we relate to other people and ourselves. This is EXTREMELY purposeful. The Human Experience, we’ll call it, is feeding a channel or, as I think of it, God: An all present, all seeing consciousness, which is hyper-learning in order to harmonize with higher frequencies to support the constant expansion and contraction of all ether and galaxies. Every soul on Earth is a fragmented part of who we once were. We self-demoted from our realm, like fallen angels, agreeing to experience pain, suffering, sin, ecstasy, all of the emotions. All of them.', 'If we wanted to get really far out, it’s like we’re a noble battery that produces frequency and just by processing experience we create more power/frequency in the battery. We decided to take one for the team. We’ve been slumming it as humans meanwhile the rest of the universes and dimensions thank us for testing our ability to just simply endure.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/universe/universe-3-4-3/', '2020-05-07T12:00:00Z', '2020-05-07T12:00:00Z'),
  ('l5608', 'why-is-there-anything-at-all', 'bekk-w', 'name', null, array['Either there is no reason, and it’s all absurd and meaningless, Or we must be something closer to gods than we think. But, will we ever know? To quote Neutral Milk Hotel- ‘How strange it is to be anything at all.''']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/universe/why-is-there-anything-at-all/', '2020-05-26T12:00:00Z', '2020-05-26T12:00:00Z'),
  ('l5775', 'why-is-there-anything-at-all', 'gissy-moon', 'name', null, array['We live in a universe that was created by a being. That being is who we call God. The reason God created the universe was so that he/she could create children to live in that universe. God created us, her children, to experience, express, share, and bask in the unconditional love that God has for us.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/universe/how-did-the-universe-begin-and-how-will-it-end-2/', '2020-05-30T12:00:00Z', '2020-05-30T12:00:00Z'),
  ('l4277', 'what-is-your-most-far-out-theory', 'j-dizzle', 'name', null, array['The Universe is vast – perhaps infinite; perhaps it transitions into another Universe and thus creates a multiverse. Yet, in all this vastness, there are only a select few elements to pick from. There are, quite likely, many other earth-like planets, many of which may be identical to Earth. It is possible that there’s another ‘you’ sitting on another Earth, or even infinite ‘you’s’ on infinite Earths.']::text[], null, 'live', true, false, false, 'https://quarxtheories.com/miscellaneous/miscellaneous-3-1-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l4275', 'what-is-your-most-far-out-theory', 'nick-s', 'name', null, array['Our human eyesight is pretty damn good, but even we don’t see every color. In dogs, for example, the world appears blue, yellow and gray (not red or green). We see a more vivid world, but also see all sorts of shades of gray. What if gray was a color(s) that we cannot see, and only appears gray to our eyes?']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/miscellaneous/miscellaneous-3-1-2/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l4272', 'what-is-your-most-far-out-theory', 'shay-p', 'name', null, array['Cats may be far more intelligent than we think they are. The ancient Egyptians,among other cultures, revered cats. They are the apex predator in every ecosystem they inhabit. They are the strongest, fastest, most agile animals in the world. They are extremely fine tuned to their surroundings, and demonstrate a meditative demeanor. Cats may be the most all-around evolved creatures on the planet, and perhaps are even a gift from another planet altogether.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/miscellaneous/miscellaneous-3-1-3/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l4269', 'what-is-your-most-far-out-theory', 'the-kid', 'name', null, array['The Earth is like an oasis in the desert of space. It somehow has access to consciousness, which, like water, all life forms want. Yet, everything in form, from rocks to trees to animals, has access to this consciousness – all that differs is how they choose to access it. Thus, what if rocks are accessing the consciousness by being like freckles – completely still and faced into the Earth. Plants/trees are like hairs, humans are like lice. All of form has a different way of connecting to the Earth just like every phone has a different charging cable.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/miscellaneous/miscellaneous-3-1-4/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l4264', 'what-is-your-most-far-out-theory', 'chiron', 'name', null, array['Theories are not the future of humanity. We need to go beyond theories to discover our true nature and to answer our deeper existential questions. I believe humans have the capacity to learn and gain knowledge not just through rationale or logic but also through feelings and sensations. I believe if we learn to open up our connections to our subtle senses, we can learn a great deal about life and our existence. Therefore, I ask if you are reading all of my answers, to read with mindfulness and feelings rather than with logic alone.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/miscellaneous/miscellaneous-3-1-5/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l4262', 'what-would-you-change-about-our-society', 'chiron', 'name', null, array['First and foremost, our education system. We need to shift our education system from one that is all about increasing our knowledge, data and information into one that transforms human perception and creativity. With that, different dimensions of knowledge and wisdom will arise and more mysteries can be uncovered.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/personal/personal-3-4-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l4072', 'what-would-you-change-about-our-society', 'j-dizzle', 'name', null, array['I would split our country into two. Right now, there is such dense gridlock that it perpetuates a mindset of separateness and exclusion. Studies have shown that there are actually 12 distinct cultures geographically throughout the country. I would not go so far as to split up into 12 countries, but by splitting into two, we would allow for more political views to be heard, more discourse, more progress, and thus a higher quality of life for people.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/personal/personal-3-4-2/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l4070', 'what-would-you-change-about-our-society', 'n-bailey', 'name', null, array['The US is the most powerful country in the world, and thus the model for countless developing nations. Yet, we have not evolved past the equivalent of an adolescent in maturity. We prioritize war over peace, profit over happiness, material possessions over environmental stewardship, intoxicants over inner work, denial over acceptance, and countless more backwards philosophies. If we do not either evolve to set a better example or step down as a world power, the human species is doomed.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/personal/personal-3-4-3/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l5762', 'what-would-you-change-about-our-society', 'delerium', 'name', null, array['I know people will hate me for saying this, but if everyone went vegan, it would reduce a lot of air/water pollution, cut methane emissions that are contributing to global warming, and allow us to make MUCH better use of arable farming land & fresh water. Meat production is pretty wasteful and polluting per calorie of food it provides.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/personal/what-would-you-change-about-our-society-3/', '2020-05-29T12:00:00Z', '2020-05-29T12:00:00Z'),
  ('l5760', 'what-would-you-change-about-our-society', 'gaia', 'name', null, array['Empathy and self-awareness. I think the main problem we have is that the large majority of the people on this planet do not introspect. They do not look at the actions they commit and how they can affect others. There are many examples regarding people who say they believe in this or that but their actions imply otherwise. Being more self-aware would help change this and I think it would make people more empathetic.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/personal/what-would-you-change-about-our-society/what-would-you-change-about-our-society-2/', '2020-05-29T12:00:00Z', '2020-05-29T12:00:00Z'),
  ('l5729', 'what-would-you-change-about-our-society', 'anna-h', 'name', null, array['I would shift our society into one that is in line with the cycles and rhythms of nature. Collectively we would honor the turning of each season alongside the changes in our own bodies and every levels. In school we would learn skills like fire-building, nonviolent communication, herb identification, and how to move emotions through our body. Everyone of every gender would come to know and respect the mysteries of the moon blood. In this way our society would gradually balance the yin and yang energies and become more grounded, loving, kind, and wise.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/personal/what-would-you-change-about-our-society/', '2020-05-29T12:00:00Z', '2020-05-29T12:00:00Z'),
  ('l4253', 'if-you-could-teach-everyone-in-the-world-one-concept-what-concept-would-have-the', 'chiron', 'name', null, array['Humility. It means surrendering our own sense of righteousness and entering the space of equanimity and empathy. Humility is also cultivating the willingness to participate in life. Rather than acting compulsively, humility means choosing to act consciously. In such a way, we can recognize our interconnectedness and our differences can be embraced and appreciated as a chance for growth.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/personal/personal-3-2-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l4068', 'if-you-could-teach-everyone-in-the-world-one-concept-what-concept-would-have-the', 'eva-lenore', 'name', null, array['Listen. Everything that is worth thinking, doing, or having starts here. We listen with all our senses – it is the act of stillness, openness, receptivity all at once. To learn to listen would open the door for understanding, which is the key to compassion, kindness, and peace. Every single conflict in human history had its origins from a misunderstanding – one that could have been resolved by deep listening from each side. My mantra is ‘Truly listen.’']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/personal/personal-3-2-2/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l4066', 'if-you-could-teach-everyone-in-the-world-one-concept-what-concept-would-have-the', 'nick-s', 'name', null, array['Compassion. We have all felt the joy and fulfillment that comes from empathy and generosity towards others (and the dissatisfaction that comes from being selfish). Likewise, we all want happiness ourselves. As the Dalai Lama says, “if we wish to be truly selfish, we should be wisely selfish.” In other words, if we wish for our own wellbeing, compassion for others rewards us with this wellbeing. Though a very clear and fundamental truth, our habits and deluded perceptions make it hard to see.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/personal/personal-3-2-3/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l5701', 'if-you-could-teach-everyone-in-the-world-one-concept-what-concept-would-have-the', 'morrie-w', 'name', null, array['Locate a deeply felt mission for each role you play in your life – make sure it answers the question “why” – and as much as possible let the mission be the guide for your actions.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/personal/if-you-could-teach-everyone-in-the-world-one-concept-what-concept-would-have-the-most-positive-impact-on-humanity/', '2020-05-28T12:00:00Z', '2020-05-28T12:00:00Z'),
  ('l5726', 'if-you-could-teach-everyone-in-the-world-one-concept-what-concept-would-have-the', 'anna-h', 'name', null, array['If I could teach everyone in the world one concept, it would be to feel–– to allow each emotion to pulse through us like a tidal wave, drinking in and breathing out every bit of grief, rage, joy, ecstasy, and despair. We live in a culture that rewards numbing, a culture that encourages us to SUPPRESS, REPRESS, and HOLD IN our emotions to the point of making ourselves sick. So we learn from a young age onward how to dampen our big emotional waves through restricting our breath and distracting ourselves. Re-learning how to feel deeply would have a positive impact on humanity because feeling coaxes hidden parts of ourselves out from the shadows so that they can be loved. Strong self love allows us to end the war with ourselves, which will ultimately end the war with all other selves.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/personal/if-you-could-teach-everyone-in-the-world-one-concept-what-would-it-be/', '2020-05-29T12:00:00Z', '2020-05-29T12:00:00Z'),
  ('l4245', 'if-you-could-start-a-country-from-scratch-what-would-it-be-like', 'chiron', 'name', null, array['Technologies invested to the wellbeing of both human and earth. Free education, healthcare, spiritual endeavors, food and water will be given. Education is dedicated into elevating human perception rather than just increasing knowledge and data. There will be no work or play as there will be no distinguishing between work and play. Leadership is done through a group council that equally represents the race and gender makeup of the society.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/personal/personal-3-1-1/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l4064', 'if-you-could-start-a-country-from-scratch-what-would-it-be-like', 'shay-p', 'name', null, array['The country would grow only as large as it could be self-sustaining (net zero emissions). It would be a resource-based economy, operating from abundance rather than scarcity. All life forms native to and living in the area would have large protected areas. The education system would be free and updated. Food would be grown locally and citizens’ healthcare would be free. Mindfulness and connection with nature would be fundamental. No prison, only rehabilitation centers. A futuristic utopia.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/personal/if-you-could-start-a-country-from-scratch-what-would-it-be-like/personal-3-1-2/', '2020-05-03T12:00:00Z', '2020-05-03T12:00:00Z'),
  ('l5744', 'if-you-could-start-a-country-from-scratch-what-would-it-be-like', 'aaron-r', 'name', null, array['Union of the American Commune – The UAC is a country that comprises all of America plus some parts of Europe that have been occupied. The capital and largest city would be Washington D.C, New York, Brasilia or any city depending on who you ask. The country is made up of about 3 provinces: North America, comprising the United States, Canada and Mexico, Central America with all of Central America and South America comprising of the old countries of South America. Keep in mind, that these provinces are further divided into several states, with each state having its own constitution and anthem as well as its own motto.', 'Government', 'The country is a Unitary One-Party Socialist Republic, however they’ve been adapting some capitalist features in order to ease tensions with the rest of the world. The country follows the historical paths and instead of having a “president”, it has a Premier which controls the American Associate Council or the Politburo for the Russians.', 'The Premier usually gives several speeches on the Victory over Europe and the May Parade. This “May Parade” is done to congratulate the soldiers who fought for the country and returned home or died.', 'The AAC is comprised of hundreds of representatives of the People’s American Party and it’s further divided into 6 people who usually give speeches, some of them being given by the Premier himself.', 'The economy of the country is doing pretty well with several economic reforms being done to ease tensions with the poor people. Homeless people make about 0.01% of the people in the UAC and there are no elite classes since they’re considered bourgeois. The 0.01% of the homeless people usually are given money to buy clothes, food or even houses.', 'Since 2037, the UAC has made several colonies on both the Moon and Mars and is planning to create the first space city in Mars by 2078. This space city will be called “New Amerika”.', 'Technology', 'The technology is amazing. You’ve got everything from plasma rifles to bioengineered shields. Conscription was introduced right before the War over Fort Malagui which almost caused a World War 3. However, the War over Fort Malagui ended in American victory.', 'The military is made of about 2.8M men, thousands of tanks, thousands of aircraft… The number will increase by 2054, however, with the UAC planning to at least have 4.1M men.', 'Land', 'That’s the Union of the American Commune.', 'Currency', 'The currency is every currency the countries used to have (i.e: Spain having the € while the US having the $).']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/personal/personal-3-1-7/', '2020-05-29T12:00:00Z', '2020-05-29T12:00:00Z'),
  ('l5742', 'if-you-could-start-a-country-from-scratch-what-would-it-be-like', 'stefan-s', 'name', null, array['If I could create an ideal country from scratch, then I would want it to be an island, because those are harder to invade and easier to defend. I would want it to not be too far off the beaten path, however, because I would want to have the possibility of beneficial trading relationships with other countries. I would want it to be far enough away from the equator to have four distinct seasons, including a winter that is cold enough to kill off a good number of pests and pathogens. However, I would still want it close enough to the equator to have a good long growing season. I would also want it to sit astride strong and steady trade winds so that the development of wind power would be feasible. Somewhere around 45 degrees of latitude – probably North latitude, and probably in the middle of the Atlantic, would be ideal.', 'I would want the island to be large enough to host a varied topography of both level land and mountains, and thus able to support a variety of basic economic activities including agriculture, forestry, mining, as well as fishing. I would want it to get a good amount of precipitation and have an abundant fresh water supply.', 'I would want this island to be large enough to support a population of as much as 5–10 million people at a minimum, and maybe more. A population of this size would be necessary to support at least one or two world-class universities and a very diversified advanced economy.', 'Flag? Maybe a green circle in the middle of a blue field?']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/personal/personal-3-1-6/', '2020-05-29T12:00:00Z', '2020-05-29T12:00:00Z')
on conflict (id) do nothing;
